  ('guardian', 'Responsável');

-- Insere permissões padrão para cada tipo de usuário se ainda não existir
INSERT INTO `pwa`.`permissions` (`user_type_id`, `can_create_event`, `can_view_all_events`, `can_receive_notifications`, `can_create_user`)
SELECT ut.id,
       CASE WHEN ut.name IN ('teacher','admin') THEN 1 ELSE 0 END,
       CASE WHEN ut.name = 'admin' THEN 1 ELSE 0 END,
       1,
       CASE WHEN ut.name = 'admin' THEN 1 ELSE 0 END
FROM `pwa`.`user_types` ut
WHERE ut.name IN ('student','teacher','admin','guardian')
  AND NOT EXISTS (SELECT 1 FROM `pwa`.`permissions` p WHERE p.user_type_id = ut.id);

