-- Banco de dados para o sistema de eventos escolares
-- Utilize: USE pwa; antes de executar

USE pwa;

-- Tabela de tipos de usuários (flexível para novos perfis)
CREATE TABLE user_types (
    id INT PRIMARY KEY AUTO_INCREMENT,
    name VARCHAR(50) NOT NULL UNIQUE, -- Ex: student, teacher, admin
    description TEXT
);

-- Tabela de permissões por tipo de usuário
CREATE TABLE permissions (
    id INT PRIMARY KEY AUTO_INCREMENT,
    user_type_id INT NOT NULL,
    can_create_event BOOLEAN DEFAULT FALSE,
    can_view_all_events BOOLEAN DEFAULT FALSE,
    can_receive_notifications BOOLEAN DEFAULT TRUE,
    FOREIGN KEY (user_type_id) REFERENCES user_types(id) ON DELETE CASCADE
);

-- Tabela de usuários (centraliza todos os tipos)
CREATE TABLE users (
    id INT PRIMARY KEY AUTO_INCREMENT,
    first_name VARCHAR(50) NOT NULL,
    last_name VARCHAR(50) NOT NULL,
    email VARCHAR(100) NOT NULL UNIQUE,
    phone VARCHAR(20),
    birth_date DATE,
    password VARCHAR(255) NOT NULL,
    cpf VARCHAR(11) NOT NULL UNIQUE,
    user_type_id INT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_type_id) REFERENCES user_types(id) ON DELETE RESTRICT
);

-- Tabela de estudantes
CREATE TABLE students (
    student_id INT PRIMARY KEY,
    class VARCHAR(50),
    registration_number VARCHAR(20) UNIQUE,
    FOREIGN KEY (student_id) REFERENCES users(id) ON DELETE CASCADE
);

-- Tabela de professores
CREATE TABLE teachers (
    teacher_id INT PRIMARY KEY,
    courses VARCHAR(255),
    FOREIGN KEY (teacher_id) REFERENCES users(id) ON DELETE CASCADE
);

-- Tabela de responsáveis
CREATE TABLE guardians (
    guardian_id INT PRIMARY KEY,
    relationship VARCHAR(50),
    student_id INT NOT NULL,
    FOREIGN KEY (guardian_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (student_id) REFERENCES users(id) ON DELETE CASCADE
);

-- Tabela de eventos
CREATE TABLE events (
    id INT PRIMARY KEY AUTO_INCREMENT,
    title VARCHAR(100) NOT NULL,
    description TEXT,
    type VARCHAR(50),
    user_id INT,
    is_public BOOLEAN DEFAULT FALSE,
    groups_combined BOOLEAN DEFAULT FALSE, -- Indica se múltiplos grupos são combinados (AND) ou não (OR)
    event_datetime DATETIME,
    event_location VARCHAR(100),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
);

-- Tabela de assinaturas para notificações push
CREATE TABLE subscriptions (
    id INT PRIMARY KEY AUTO_INCREMENT,
    endpoint TEXT NOT NULL,
    keys_p256dh TEXT NOT NULL,
    keys_auth TEXT NOT NULL,
    user_id INT,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- Tabela de grupos (para organizar usuários em grupos específicos)
CREATE TABLE `groups` (
    id INT PRIMARY KEY AUTO_INCREMENT,
    name VARCHAR(100) NOT NULL,
    description TEXT,
    group_type ENUM('turma', 'turno', 'area_ensino', 'curso', 'custom') DEFAULT 'custom',
    created_by INT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
);

-- Tabela de relacionamento entre usuários e grupos
CREATE TABLE user_groups (
    id INT PRIMARY KEY AUTO_INCREMENT,
    user_id INT NOT NULL,
    group_id INT NOT NULL,
    joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(user_id, group_id),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (group_id) REFERENCES `groups`(id) ON DELETE CASCADE
);

-- Tabela de relacionamento entre eventos e grupos
CREATE TABLE event_groups (
    id INT PRIMARY KEY AUTO_INCREMENT,
    event_id INT NOT NULL,
    group_id INT NOT NULL,
    UNIQUE(event_id, group_id),
    FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE,
    FOREIGN KEY (group_id) REFERENCES `groups`(id) ON DELETE CASCADE
);

-- Tabela de notificações agendadas (fila de envio de push)
-- Campos adicionais: attempts (número de tentativas), last_error (último erro registrado)
CREATE TABLE scheduled_notifications (
  id INT PRIMARY KEY AUTO_INCREMENT,
  event_id INT NOT NULL,
  payload JSON NOT NULL,
  scheduled_at DATETIME NOT NULL,
  sent TINYINT(1) DEFAULT 0,
  attempts INT DEFAULT 0,
  last_error TEXT NULL,
  last_attempt_at DATETIME NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE
);